using Godot;
using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Threading.Tasks;
using Zhanguo.Desktop.Layout;
using static WorldMap;

public partial class Desktop
{
    // Offline fixture generated by an ordinary v13 game, including real
    // receipts and settlement deltas; never calls an external model.
    private async Task ReviewLedger(string path)
    {
        try
        {
            _status.Text="独立离线收支与排版检查";
            var input=JsonNode.Parse(File.ReadAllText(OS.GetEnvironment("ZHANGUO_LEDGER_REVIEW")))!.AsObject();
            var frame=input["frame"]!.DeepClone().AsObject();JsonObject? chosen=null;
            foreach(var row in input["beats"]!.AsArray())
            {
                var beat=row!.AsObject();
                if(beat["ledger"]!=null){chosen=beat;break;}
                DesktopScene.Apply(frame,beat["delta"]!.AsObject());
            }
            if(chosen==null)throw new Exception("离线样例没有国家结算");
            ApplyFrame(frame);_timelinePeriod=I(chosen["ledger"]!["period"]);
            _map.BeginBeat(chosen,true);ShowNationalSettlement(chosen);
            _bannerTitle.Text=S(chosen["turn_title"]);_bannerText.Text=S(chosen["text"]);
            string stem=Path.ChangeExtension(path,null);var checks=new List<object>();
            async Task Check(Vector2I size,int points,float scale)
            {
                var physical=new Vector2I((int)(size.X*scale),(int)(size.Y*scale));
                GetWindow().ContentScaleSize=size;GetWindow().Size=physical;
                _ledgerTextSize=points;ApplyDisplayOptions(false);
                await ToSignal(GetTree().CreateTimer(.6),SceneTreeTimer.SignalName.Timeout);
                ValidateLedgerLayout();
                var view=NationLedger.Read(_map.Frame!,_ledgerActor)!;
                if(_ledgerStocks.GetChildCount()!=view.Stocks.Count*3||view.Actor!=S(chosen["actor"])||view.FlowPeriod!=_timelinePeriod-1)
                    throw new Exception("国家、流量期数或资源行与实际演出不同步");
                await Screenshot(stem+$"-{size.X}x{size.Y}-{points}px-{scale:0.00}x.png");
                checks.Add(new { width=size.X,height=size.Y,physical_width=physical.X,physical_height=physical.Y,render_scale=scale,
                    os_dpi_changed=false,font_size=points,actor=view.Actor,period=view.Period,flow_period=view.FlowPeriod,
                    stocks=view.Stocks,ledger_within_viewport=true,settlement_within_viewport=true,overlap=false });
            }
            foreach(var size in new[]{new Vector2I(1920,1080),new Vector2I(1440,900),new Vector2I(1280,720),new Vector2I(1024,768)})
                foreach(int points in new[]{16,20})await Check(size,points,1);
            foreach(float scale in new[]{1.25f,1.5f})foreach(int points in new[]{16,20})await Check(new Vector2I(1280,720),points,scale);
            File.WriteAllText(path+".json",JsonSerializer.Serialize(checks,new JsonSerializerOptions { WriteIndented=true }));
            GD.Print("LEDGER_REVIEW_OK "+path);GetTree().Quit();
        }
        catch(Exception e){GD.PrintErr(e);GetTree().Quit(3);}
    }
}
